from taf.ul.bts_components.component.smod import Smod
from taf.rfrl.procedures.resources.python.SCF import get_rus_protocols_with_mapped_ids
from taf.rfrl.procedures.resources.python.logger import (
    log_result,
    log_operation,
    log_step,
)

from taf.rfrl.procedures.resources.python.connections import (
    get_ssh_connection_credentials,
)
from taf.rfrl.procedures.resources.python.sw_guard.exceptions import SwMismatchError
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import (
    get_rmod_indexes,
    get_rmod_details_with_rf_sw,
)


class SwGuardSingleton(object):
    _instance = None

    def __new__(cls, *args, **kwargs):
        if not isinstance(cls._instance, cls):
            cls._instance = object.__new__(cls)
        return cls._instance

    def __init__(self):
        self.smod = Smod()
        self.rus_type_with_ids = None
        self.rus_sws_from_targetBD = None
        self.enb_rus_sws_from_targetBD = None
        self.rus_details = None

    def compare_rus_sw_version(self, connection, bts_type='GNB', raise_exception=True):
        """
        Compares RFSW declared by targetBD file with RFSW resolved by admin API.

        :param connection: AdminConnection object or, if used, string name alias
        :type connection: AdminConnection or str
        :param bts_type: type of bts, can be GNB or ENB; defaults to GNB
        :type bts_type: str
        :param raise_exception: Indicates whether to rise an exception or return bool value if RFSWs match each other
                                and `raise_exception` was set to `True`
        :type raise_exception: bool
        :returns: information if RUs software versions match
        :rtype: bool
        :raises: SwMismatchError exception whether RFSWs do not match each other and `raise_exception`
                 was set to `True`
        """
        self._get_ru_details_from_admin_api(connection)

        self._get_sws_from_targetBD(connection, bts_type)

        return self._compare_rus_sw_version(raise_exception)

    def compare_enb_rus_sw_version(self, connection, raise_exception=True):
        """
        Compares ENB RFSW declared by targetBD file with RFSW resolved by admin API.

        :param connection: AdminConnection object or, if used, string name alias
        :type connection: AdminConnection or str
        :param raise_exception: Indicates whether to rise an exception or return bool value if RFSWs do not match
                                each other and `raise_exception` was set to `True`
        :type raise_exception: bool
        :returns: information if RUs software versions match
        :rtype: bool
        :raises: SwMismatchError exception whether RFSWs do not match each other and `raise_exception`
                 was set to `True`
        """
        self._get_ru_details_from_admin_api(connection)

        self._get_enb_sws_from_targetBD(connection)

        return self._compare_enb_rus_sw_version(raise_exception)

    def _compare_rus_sw_version(self, raise_exception):
        log_operation("SW version compare procedure initialized ...")

        for ru_detail_from_admin, ru_sw_from_targetBD in zip(
            sorted(self.rus_details, key=lambda x: x["sw_version"]),
            sorted(self.rus_sws_from_targetBD)
        ):
            log_step("Checking HW: {} - {}".format(ru_detail_from_admin["serial_number"],
                                                   ru_detail_from_admin["sw_version"]))
            if not ru_sw_from_targetBD == ru_detail_from_admin["sw_version"]:
                error_message = "SW version from targetBD does not match actual SW version on RU.\n" \
                    "RU type: {}, serial number: {},\n" \
                    "{} != {}\n".format(
                        ru_detail_from_admin["product_name"],
                        ru_detail_from_admin["serial_number"],
                        ru_sw_from_targetBD,
                        ru_detail_from_admin["sw_version"]
                    )
                if raise_exception:
                    raise SwMismatchError(error_message)

                log_result(error_message)
                return False

        log_result("SW version compare procedure finished successfully")
        return True

    def _get_ru_details_from_admin_api(self, connection):
        log_operation("Getting rfsws from admin api ...")

        self.rus_details = get_rmod_details_with_rf_sw(connection)

        log_result(
            "Rfsws read from admin api: {}".format(
                [ru_detail["sw_version"] for ru_detail in self.rus_details]
            )
        )

    def _get_sws_from_targetBD(self, connection, bts_type):
        log_operation("Getting rfsws from targetBD ...")

        rus_match_list = self._match_ru_type_with_protocol(connection)
        credentials = get_ssh_connection_credentials(bts_type=bts_type)

        try:
            self.smod.connect_to(credentials['host'], credentials['username'], credentials['password'])
            self.rus_sws_from_targetBD = [
                self.smod.get_rfsw_from_targetbd(
                    radio_type=ru_detail["ru_type"], radio_protocol_type=ru_detail["ru_protocol"])
                for ru_detail in rus_match_list
            ]

        finally:
            self.smod.close_connection()

        log_result("Rfsws read from targetBD: {}".format(self.rus_sws_from_targetBD))

    def _match_ru_type_with_protocol(self, connection, bts_type="GNB"):
        match_list = []

        for ru_id_protocol in get_rus_protocols_with_mapped_ids(get_rmod_indexes(connection=connection), bts_type):
            for ru_details in self.rus_details:
                if ru_id_protocol["rmod_id"] == ru_details["rmod_id"]:
                    match_list.append(
                        {
                            "ru_type": ru_details["product_name"],
                            "ru_protocol": ru_id_protocol["protocol"],
                        }
                    )

        return match_list

    def _get_enb_sws_from_targetBD(self, connection):
        log_operation("Getting eNB rfsws from targetBD ...")

        rus_match_list = self._match_ru_type_with_protocol(connection, "ENB")
        credentials = get_ssh_connection_credentials(bts_type="ENB")

        try:
            self.smod.connect_to(credentials['host'], credentials['username'], credentials['password'])
            self.enb_rus_sws_from_targetBD = [
                self.smod.get_enb_rfsw_from_targetbd_with_radio_type(
                    radio_type=ru_details["ru_type"])
                for ru_details in rus_match_list
            ]

        finally:
            self.smod.close_connection()

        log_result("RFSWs for eNB rmods read from targetBD: {}".format(self.rus_sws_from_targetBD))

    def _compare_enb_rus_sw_version(self, raise_exception):
        log_operation("Comparing eNB rmods sw versions ...")

        for ru_detail_from_admin, enb_rus_sws_from_targetBD in zip(
            sorted(self.rus_details, key=lambda x: x["product_name"]),
            sorted(self.enb_rus_sws_from_targetBD, key=lambda x: x["radio_type"])
        ):
            log_step("Checking eNB rmod with sn: {} - {}".format(ru_detail_from_admin["serial_number"],
                                                                 ru_detail_from_admin["sw_version"]))
            if not ru_detail_from_admin["sw_version"] in enb_rus_sws_from_targetBD["sw_versions"]:
                error_message = "SW version from targetBD does not match actual SW version on RU.\n" \
                    "RU type: {}, serial number: {},\n" \
                    "{} != {}\n".format(
                        ru_detail_from_admin["product_name"],
                        ru_detail_from_admin["serial_number"],
                        enb_rus_sws_from_targetBD["sw_versions"],
                        ru_detail_from_admin["sw_version"]
                    )
                if raise_exception:
                    raise SwMismatchError(error_message)

                log_result(error_message)
                return False

        log_result("SW version compare procedure finished successfully")
        return True
